var SITE = {
    init: function() {
        console.log("Last Minute Deals | author: YiCOSA yozenci@gmail.com");

        var myElement = document.getElementById("border");

        myElement.addEventListener("click", function() {
            // Enabler.exit('Background Exit');
            window.open(clickTag);
        });

        // Call the animate function
        SITE.loadLottie2(); 
        TweenLite.delayedCall(0, SITE.animate);

    },

    loadLottie: function() {
        SITE.lottieAnim = lottie.loadAnimation({
            container: document.getElementById('lottie-container'),
            renderer: 'svg',
            loop: true,
            autoplay: false,
            animationData: jsonAnim // Update with your JSON path
        });
    },

    loadLottie2: function() {
        SITE.lottieAnim2 = lottie.loadAnimation({
            container: document.getElementById('lottie-container-2'),
            renderer: 'svg',
            loop: false,
            autoplay: false,
            animationData: jsonAnim2 // Update with your JSON path
        });
    },

    playLottie: function() {
        if (SITE.lottieAnim) {
            const lottieContainer = document.getElementById("lottie-container");
            lottieContainer.style.opacity = "1";
            SITE.lottieAnim.goToAndPlay(0, true);
        }
    },

    playLottie2: function() {
        if (SITE.lottieAnim2) {
            const lottieContainer2 = document.getElementById("lottie-container-2");
            lottieContainer2.style.opacity = "1";
            SITE.lottieAnim2.goToAndPlay(0, true);
        }
    },

    maskOut: function() {
        const masktl = new TimelineMax({repeat: 0, repeatDelay: 2});
        masktl.to(["#mask"], 0.3, {autoAlpha: 0, ease: Power1.easeIn}, "+=0.3")
        ;
    },
    maskIn: function() {
        const masktl = new TimelineMax({repeat: 0, repeatDelay: 2});
        masktl.to(["#mask"], 0.3, {autoAlpha: 1, ease: Power1.easeIn}, "+=0")
        ;
    },
    imgMaskIn: function() {
        const imgmasktl = new TimelineMax({repeat: 0, repeatDelay: 2});
        imgmasktl.to(["#img_mask"], 0.1, {autoAlpha: 1}, "+=0")
        ;
    }, 

    imgMaskOut: function() {
        const imgmasktl = new TimelineMax({repeat: 0, repeatDelay: 2});
        imgmasktl.to(["#img_mask"], 0.1, {autoAlpha: 0}, "+=0")
        ;
    },          

    animate: function() {   

        //cta animation
        const container = document.getElementById('border');
        const cta3 = document.getElementById('cta3');
        const cta4 = document.getElementById('cta4');

        const pulseSpeed = 0.25;
        const pulseScale = 1.15;
        const pulseScale2 = 1.05;        

        // Initial element position settings
        // TweenLite.set("#c2", { scale: 0.85 });
        // Initial element position settings
        TweenLite.set("#mask", {y: 280 });
        TweenLite.set("#card", { y: 280 });
        TweenLite.set("#c11", {y: -5 });
        TweenLite.set("#img1", {x: 336 });
        TweenLite.set("#bg3", {y: 187 });
        TweenLite.set("#bellboy1", { y: 207 });
        TweenLite.set("#speechline1", { y: 5 });
        TweenLite.set("#c2", { y: 5 });

        // Shadow start positions

        TweenLite.set(["#c12","#s12"], { x:159, y:140 });
        TweenLite.set(["#c13","#s13"], { x:159, y:140 });
        TweenLite.set(["#c14","#s14"], { x:159, y:140 })
        // TweenLite.set(["#shadow_end"], { x:41, y:38 });
        
        const copyDur = 0.2;
        const copyDel = "+=0";
        const copyEase = Power1.easeOut;
        const copyEase2 = Power1.easeIn;

        // Create a GSAP timeline
        const timeline = new TimelineMax({repeat: 0, repeatDelay: 2});
        
        // tlz
        // document.getElementById("container").style.overflow = "visible";
        // document.getElementById("shadow_end").style.zIndex = 400;
        
        
        // Set #container to be visible
        timeline.to(["#container"], 0, {autoAlpha: 1}, "+=0")
        .to(["#logo1"], 0.5, {y:120, ease: Power1.easeIn}, "+=0.65")
        .to(["#logo1"], 0.2, {autoAlpha:0}, "-=0.25")

        // Frame 1    
        .to("#c11a", 0, { autoAlpha: 1 }, "+=0.2")
        .to("#c11a", 0.12, { y: 5, ease: "none"})
        .to("#c11a", 0.12, { y: 0, ease: Power1.easeOut})
        .to("#c11b", 0, { autoAlpha: 1 }, "-=0.025")
        .to("#c11b", 0.12, { y: 5, ease: "none"})
        .to("#c11b", 0.12, { y: 0, ease: Power1.easeOut})      

        .to(["#s12","#c12"], 0, { autoAlpha: 1 }, copyDel)
        .to(["#s12","#c12"], 0.3, {x:0, y: 0, ease: Power1.easeOut}, copyDel)

        .to(["#s13","#c13"], 0, { autoAlpha: 1 }, "-=0.15")
        .to(["#s13","#c13"], 0.3, {x:0, y: 0, ease: Power1.easeOut}, "-=0.15")

        .to(["#s14","#c14"], 0, { autoAlpha: 1 }, "-=0.2")
        .to(["#s14","#c14"], 0.3, {x:0, y: 0, ease: Power1.easeOut}, "-=0.15")
        .set(["#shadow_end"], { autoAlpha:1 })


        .to(["#shadow_end","#s12","#c12","#s13","#c13","#s14","#c14"], 0.5, {x:"-=250", y: "-=250", ease: Power1.easeIn}, "+=1.5")
        .to(["#shadow_end"], 0.4, {scale:3, ease:Power1.easeIn, z:0.01}, "+=0")


        .to(["#img1", "#bg2"], 0.45, {x:"-=336", ease: Power1.easeOut}, "-=0.1")
        .to(["#img1"], 2, {z:0.01, scale:1.05})

        .to(["#card","#mask"], 0.55, {y:157, ease: Power1.easeOut},"-=2.2")

        .to(["#bg3"], 0, { autoAlpha: 1 }, "-=0.5")     
        .to(["#img1", "#bg3"], 0.5, {y:"-=187", ease: "none"}, "-=0.5")
        .to(["#bellboy1"], 0.5, {y:"-=187", ease: Power1.easeOut}, "-=0.5")

        .to(["#speechline1","#c2"], 0, { autoAlpha: 1 }, "+=0")
        .to(["#speechline1","#c2"], 0.25, {y: 0, ease: Power1.easeOut},"+=0")
        
        .to(["#card","#mask","#speechline1","#c2","#bellboy1"], 0.55, {y:-123, ease: Power1.easeIn, onStart:SITE.maskIn},"+=2")
        .to(["#logo2"], 0.6, {autoAlpha:1, ease: Power1.easeOut},"-=0.2")
        .to(["#tac"], 0.2, {autoAlpha:1, ease: Power1.easeOut, onStart:SITE.playLottie2 },"-=0")
       
        ;
        
        timeline.play();
        // document.getElementById('guide').style.backgroundImage = "url('cta1.png')";
        // timeline.pause(0);
        console.log(document.title, "Animation length: ", timeline.duration(),"Total length: ", (timeline.repeat() + 1)*timeline.duration());

    }
};

